import React, { useState } from "react";
import "./App.css";
import axios from "axios";

function App() {
  const [formData, setFormData] = useState({
    hs_avg: "",
    first_term_gpa: "",
    math_score: "",
    english_grade: ""
  });

  const [result, setResult] = useState(null);
  const [loading, setLoading] = useState(false);

  const handleChange = (e) => {
    setFormData({
      ...formData,
      [e.target.name]: e.target.value
    });
  };

  const handleSubmit = async (e) => {
    e.preventDefault();
    setLoading(true);

    try {
      const response = await axios.post(
        "http://localhost:5000/predict", // backend URL
        {
          hs_avg: Number(formData.hs_avg),
          first_term_gpa: Number(formData.first_term_gpa),
          math_score: Number(formData.math_score),
          english_grade: Number(formData.english_grade)
        }
      );

      setResult(response.data);
    } catch (error) {
      console.error(error);
      alert("Backend not connected yet!");
    }

    setLoading(false);
  };

  return (
  <div className="app">
    <div className="card">
      <h1>🎓 Student Success Predictor</h1>

      <form onSubmit={handleSubmit} className="form">
        <div className="input-group">
          <label>High School Average</label>
          <input name="hs_avg" onChange={handleChange} />
        </div>

        <div className="input-group">
          <label>First Term GPA</label>
          <input name="first_term_gpa" onChange={handleChange} />
        </div>

        <div className="input-group">
          <label>Math Score</label>
          <input name="math_score" onChange={handleChange} />
        </div>

        <div className="input-group">
          <label>English Grade</label>
          <input name="english_grade" onChange={handleChange} />
        </div>

        <button type="submit">
          {loading ? "Predicting..." : "Predict"}
        </button>
      </form>

      {result && (
        <div className="results">
          <h2>📊 Results</h2>
          <div className="result-item">
            Completion: {result.completion === 1 ? "Yes" : "No"}
          </div>
          <div className="result-item">
            Persistence: {result.persistence === 1 ? "Yes" : "No"}
          </div>
          <div className="result-item">
            GPA: {result.gpa}
          </div>
          <div className="result-item">
            Performance: {result.performance}
          </div>
        </div>
      )}
    </div>
  </div>
);
}

export default App;









